def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate the full-width/full-height separator lines.
    row_seps = [r for r, row in enumerate(grid) if all(v == 5 for v in row)]
    col_seps = [c for c in range(w) if all(grid[r][c] == 5 for r in range(h))]
    row_bounds = [-1] + row_seps + [h]
    col_bounds = [-1] + col_seps + [w]
    row_panels = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_panels = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]

    # Palette: the marker color in the first panel of each panel row.
    palette = []
    for r0, r1 in row_panels:
        colors = {grid[r][c] for r in range(r0, r1) for c in range(col_panels[0][0], col_panels[0][1]) if grid[r][c] != 0}
        palette.append(next(iter(colors)))

    # The non-empty panel outside the palette column defines the repeated shape.
    separator = grid[row_seps[0]][0] if row_seps else grid[0][col_seps[0]]
    shape = None
    for pr, (r0, r1) in enumerate(row_panels):
        for pc, (c0, c1) in enumerate(col_panels[1:], start=1):
            pts = [(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] not in (0, separator)]
            if pts:
                shape = pts
                break
        if shape is not None:
            break
    if shape is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    for pr, (r0, r1) in enumerate(row_panels):
        for c0, c1 in col_panels:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0
            for dr, dc in shape:
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = palette[pr]
    return out

