    full_rows = [(r, row[0]) for r, row in enumerate(grid)
                 if row[0] != 0 and all(v == row[0] for v in row)]
    full_cols = [(c, grid[0][c]) for c in range(w)
                 if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    candidates = [color for _, color in full_rows + full_cols]
    separator = max(set(candidates), key=candidates.count)
    row_seps = [r for r, color in full_rows if color == separator]
    col_seps = [c for c, color in full_cols if color == separator]

    rb = [-1] + row_seps + [h]
